def _safe_file(name: str, allowed_suffixes: tuple[str, ...] | None = None) -> Path:
    """Resolve a filename only within the script directory."""
    name = Path(unquote(name)).name
    if not name:
        raise ValueError("Missing filename")
    path = (ROOT / name).resolve()
    if path.parent != ROOT.resolve():
        raise ValueError("Invalid path")
    if allowed_suffixes and not any(name.lower().endswith(s) for s in allowed_suffixes):
        raise ValueError("Unsupported file type")
    return path


def _transform_import_html(text: str) -> str:
    """Prepare an HTML movie for one-time structured import.

    This transformed copy is served only to the hidden importer iframe. It is
    never written to disk and never stored in project JSON.
    """
    # External/module application integrations are irrelevant to the importer
    # and can fail on localhost, so remove only module scripts.
    text = re.sub(
        r"<script\b[^>]*\btype\s*=\s*(['\"])module\1[^>]*>.*?</script\s*>",
        "",
        text,
        flags=re.IGNORECASE | re.DOTALL,
    )
    text = re.sub(
        r"<script\b[^>]*\btype\s*=\s*(['\"])module\1[^>]*/\s*>",
        "",
        text,
        flags=re.IGNORECASE,
    )

    # Expose the movie's existing sequence registry without changing the source
    # file. This lets the importer evaluate animation functions at arbitrary
    # normalized progress values instead of slowly scrolling through the film.
    text, count = re.subn(
        r"\bconst\s+sequences\s*=\s*\[",
        "const sequences = window.__editorSequences = [",
        text,
        count=1,
    )
    if not count:
        text = text.replace(
            "<head>",
            "<head><script>window.__editorSequences=[];</script>",
            1,
        )

    freeze_css = """
<style id="__movie_editor_import_freeze">
html { scroll-behavior:auto !important; }
*, *::before, *::after {
    animation-play-state: paused !important;
    transition-duration: 0s !important;
    transition-delay: 0s !important;
}
site-navbar, .mobile-landscape { display:none !important; }
</style>
<script>window.__MOVIE_EDITOR_IMPORT__ = true;</script>
"""
    if "</head>" in text.lower():
        idx = text.lower().rfind("</head>")
        text = text[:idx] + freeze_css + text[idx:]
    else:
        text = freeze_css + text
    return text


class Handler(BaseHTTPRequestHandler):
    server_version = "Unlim8tedMovieEditor/1.0"

    def log_message(self, fmt: str, *args) -> None:
        # Keep the terminal useful without printing every asset/source request.
        if self.path.startswith("/api/") and not self.path.startswith("/api/files"):
            sys.stdout.write("[editor] " + (fmt % args) + "\n")

    def _send(self, body: bytes, content_type: str, status: int = 200) -> None:
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.end_headers()
        self.wfile.write(body)

    def _json(self, obj, status: int = 200) -> None:
        body = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self._send(body, "application/json; charset=utf-8", status)

    def _error(self, message: str, status: int = 400) -> None:
        self._send(message.encode("utf-8"), "text/plain; charset=utf-8", status)

    def do_GET(self) -> None:  # noqa: N802
        parsed = urlparse(self.path)
        q = parse_qs(parsed.query)
        try:
            if parsed.path == "/":
                self._send(EDITOR_HTML.encode("utf-8"), "text/html; charset=utf-8")
                return

            if parsed.path == "/health":
                self._send(b"ok", "text/plain; charset=utf-8")
                return

            if parsed.path == "/app-icon.svg":
                self._send(APP_ICON_SVG.encode("utf-8"), "image/svg+xml; charset=utf-8")
                return

            if parsed.path == "/api/files":
                kind = q.get("kind", ["html"])[0]
                files = []
                for p in ROOT.iterdir():
                    if not p.is_file():
                        continue
                    if kind == "html":
                        ok = p.suffix.lower() in {".html", ".htm"}
                    else:
                        ok = p.suffix.lower() == ".json"
                        if ok:
                            try:
                                with p.open("r", encoding="utf-8") as f:
                                    prefix = f.read(4096)
                                ok = PROJECT_FORMAT in prefix
                            except OSError:
                                ok = False
                    if ok:
                        st = p.stat()
                        files.append(
                            {
                                "name": p.name,
                                "size": st.st_size,
                                "modified": time.strftime(
                                    "%Y-%m-%d %H:%M", time.localtime(st.st_mtime)
                                ),
                            }
                        )
                files.sort(key=lambda x: x["name"].lower())
                self._json({"files": files})
                return

            if parsed.path == "/api/import-source":
                path = _safe_file(q.get("name", [""])[0], (".html", ".htm"))
                if not path.exists():
                    self._error("HTML file not found", 404)
                    return
                text = path.read_text(encoding="utf-8", errors="replace")
                transformed = _transform_import_html(text)
                self._send(transformed.encode("utf-8"), "text/html; charset=utf-8")
                return

            if parsed.path == "/api/raw":
                path = _safe_file(q.get("name", [""])[0], (".html", ".htm"))
                if not path.exists():
                    self._error("File not found", 404)
                    return
                self._send(path.read_bytes(), "text/html; charset=utf-8")
                return

            if parsed.path == "/api/project":
                path = _safe_file(q.get("name", [""])[0], (".json",))
                if not path.exists():
                    self._error("Project file not found", 404)
                    return
                data = json.loads(path.read_text(encoding="utf-8"))
                if data.get("format") != PROJECT_FORMAT:
                    self._error("Not an Unlim8ted Movie Project", 400)
                    return
                self._json(data)
                return

            self._error("Not found", 404)
        except (ValueError, json.JSONDecodeError) as exc:
            self._error(str(exc), 400)
        except Exception as exc:  # pragma: no cover - server guard
            self._error(f"Server error: {exc}", 500)

    def do_POST(self) -> None:  # noqa: N802
        parsed = urlparse(self.path)
        try:
            length = int(self.headers.get("Content-Length", "0"))
            if length > 200 * 1024 * 1024:
                self._error("Request too large", HTTPStatus.REQUEST_ENTITY_TOO_LARGE)
                return
            payload = (
                json.loads(self.rfile.read(length).decode("utf-8")) if length else {}
            )

            if parsed.path == "/api/save":
                name = payload.get("name", "")
                project = payload.get("project")
                if (
                    not isinstance(project, dict)
                    or project.get("format") != PROJECT_FORMAT
                ):
                    self._error("Invalid project data", 400)
                    return
                path = _safe_file(name, (".json",))
                if not path.name.lower().endswith(".json"):
                    path = path.with_suffix(".json")
                project.setdefault("meta", {})["modifiedAt"] = time.strftime(
                    "%Y-%m-%dT%H:%M:%S%z"
                )

                # Explicitly reject accidental raw-HTML embedding at the top
                # level. Structured asset node trees are expected; source HTML
                # strings are not.
                for forbidden in ("html", "sourceHtml", "rawHtml", "documentHtml"):
                    if forbidden in project:
                        self._error(
                            f"Project contains forbidden raw HTML field: {forbidden}"
                        )
                        return

                tmp = path.with_suffix(path.suffix + ".tmp")
                tmp.write_text(
                    json.dumps(project, ensure_ascii=False, indent=2), encoding="utf-8"
                )
                os.replace(tmp, path)
                self._json({"ok": True, "name": path.name, "size": path.stat().st_size})
                return

            self._error("Not found", 404)
        except (ValueError, json.JSONDecodeError) as exc:
            self._error(str(exc), 400)
        except Exception as exc:  # pragma: no cover - server guard
            self._error(f"Server error: {exc}", 500)


def _find_blender_executable() -> Path | None:
    """Locate Blender without depending on a particular operating system install."""
    candidates: list[Path] = []
    for variable in ("BLENDER_EXECUTABLE", "BLENDER_PATH"):
        configured = os.environ.get(variable, "").strip().strip('"')
        if configured:
            candidates.append(Path(configured).expanduser())

    on_path = shutil.which("blender") or shutil.which("blender.exe")
    if on_path:
        candidates.append(Path(on_path))

    if sys.platform == "darwin":
        candidates.extend(
            [
                Path("/Applications/Blender.app/Contents/MacOS/Blender"),
                Path.home() / "Applications/Blender.app/Contents/MacOS/Blender",
            ]
        )
    elif os.name == "nt":
        for variable in ("ProgramFiles", "ProgramW6432", "ProgramFiles(x86)"):
            root = os.environ.get(variable)
            if not root:
                continue
            blender_root = Path(root) / "Blender Foundation"
            if blender_root.is_dir():
                candidates.extend(
                    sorted(blender_root.glob("Blender*/blender.exe"), reverse=True)
                )
            candidates.append(
                Path(root) / "Steam/steamapps/common/Blender/blender.exe"
            )
    else:
        candidates.extend(
            [
                Path("/usr/bin/blender"),
                Path("/usr/local/bin/blender"),
                Path("/snap/bin/blender"),
                Path.home() / ".local/bin/blender",
            ]
        )

    seen: set[str] = set()
    for candidate in candidates:
        try:
            resolved = candidate.resolve()
        except OSError:
            resolved = candidate
        key = os.path.normcase(str(resolved))
        if key in seen:
            continue
        seen.add(key)
        if resolved.is_file() and (os.name == "nt" or os.access(resolved, os.X_OK)):
            return resolved
    return None


def _materialize_blender_visuals(visuals: dict, directory: Path) -> dict:
    """Turn browser-created PNG data URLs into temporary files Blender can pack."""
    if not isinstance(visuals, dict):
        return {"version": 1, "assets": {}}
    assets = visuals.get("assets")
    if not isinstance(assets, dict):
        visuals["assets"] = {}
        return visuals

    total_bytes = 0
    for asset_index, (asset_id, visual) in enumerate(assets.items()):
        if not isinstance(visual, dict):
            continue
        parts = visual.get("parts")
        if not isinstance(parts, list):
            continue
        for part_index, part in enumerate(parts):
            if not isinstance(part, dict):
                continue
            svg_data = part.pop("svgData", None)
            if isinstance(svg_data, str) and svg_data.lstrip().startswith("<svg"):
                svg_raw = svg_data.encode("utf-8")
                total_bytes += len(svg_raw)
                if total_bytes > 750 * 1024 * 1024:
                    raise ValueError("Blender asset visuals exceed the 750 MB export limit.")
                svg_path = directory / f"asset_{asset_index:05d}_part_{part_index:04d}.svg"
                svg_path.write_bytes(svg_raw)
                part["svgPath"] = str(svg_path)
            data_url = part.pop("imageData", None)
            if not isinstance(data_url, str) or not data_url:
                continue
            try:
                header, encoded = data_url.split(",", 1)
                if "image/png" not in header.lower() or ";base64" not in header.lower():
                    continue
                raw = base64.b64decode(encoded, validate=True)
            except (ValueError, binascii.Error):
                continue
            total_bytes += len(raw)
            if total_bytes > 750 * 1024 * 1024:
                raise ValueError("Blender asset visuals exceed the 750 MB export limit.")
            image_path = directory / f"asset_{asset_index:05d}_part_{part_index:04d}.png"
            image_path.write_bytes(raw)
            part["imagePath"] = str(image_path)
    return visuals


def _ensure_pywebview(auto_install: bool = True):
    """Import pywebview, optionally installing it for this Python environment."""
    try:
        import webview  # type: ignore

        return webview
    except ImportError:
        if not auto_install:
            raise RuntimeError(
                "pywebview is required for the desktop editor. Install it with: "
                f"{sys.executable} -m pip install pywebview"
            )
        print("pywebview is not installed. Installing it now...")
        subprocess.check_call([sys.executable, "-m", "pip", "install", "pywebview"])
        import webview  # type: ignore

        return webview


def _start_editor_server() -> tuple[ThreadingHTTPServer, str]:
    """Start localhost serving and prove the worker is accepting requests.

    Binding the socket is not enough: on Windows the GUI/webview thread could
    navigate before the new HTTP worker had entered serve_forever(), leaving
    WebView2 on a navigation that sometimes never recovered.
    """
    server = ThreadingHTTPServer(("127.0.0.1", 0), Handler)
    server.daemon_threads = True
    thread = threading.Thread(
        target=server.serve_forever, name="editor-http", daemon=True
    )
    thread.start()
    host, port = server.server_address[:2]
    url = f"http://{host}:{port}/"
    deadline = time.monotonic() + 5.0
    last_error = None
    while time.monotonic() < deadline:
        try:
            import urllib.request
            with urllib.request.urlopen(url + "health", timeout=0.35) as response:
                if response.status == 200 and response.read(8).startswith(b"ok"):
                    return server, url
        except Exception as exc:
            last_error = exc
            time.sleep(0.025)
    server.shutdown()
    server.server_close()
    raise RuntimeError(f"Editor HTTP server failed to become ready: {last_error}")


def _ensure_app_icon() -> Path:
    APP_ICON.write_text(APP_ICON_SVG, encoding="utf-8")
    return APP_ICON


class DesktopApi:
    """Small native bridge used only for desktop file saving.

    HTML and JSON loading are handled by normal file inputs inside the webview,
    which invoke the operating system's file picker. No source movie HTML is compiled into this Python file.
    """

    def __init__(self, webview_module):
        # IMPORTANT: pywebview recursively exposes/inspects public attributes of
        # js_api objects. Keeping a Window or the webview module public here can
        # make it descend into window.native / WebView2 COM objects during
        # startup, causing recursion and cross-UI-thread COM access. Keep all
        # native references private; only callable bridge methods stay public.
        self._webview = webview_module
        self._window = None
        self._blender_executable = _find_blender_executable()

    def attach(self, window) -> None:
        self._window = window

    def save_project(
        self,
        project_text: str,
        suggested_name: str,
        current_path: str = "",
        save_as: bool = False,
    ) -> dict:
        if self._window is None:
            return {"ok": False, "error": "Editor window is not ready."}

        path: Path | None = None
        if current_path and not save_as:
            candidate = Path(current_path).expanduser()
            if candidate.suffix.lower() == ".json":
                path = candidate

        if path is None:
            dialog_type = getattr(
                getattr(self._webview, "FileDialog", object),
                "SAVE",
                getattr(self._webview, "SAVE_DIALOG", 30),
            )
            result = self._window.create_file_dialog(
                dialog_type,
                directory=str(ROOT),
                save_filename=suggested_name,
                file_types=("Movie project (*.movie.json;*.json)", "JSON (*.json)"),
            )
            if not result:
                return {"ok": False, "cancelled": True}
            selected = result[0] if isinstance(result, (tuple, list)) else result
            path = Path(selected)

        if not path.name.lower().endswith(".json"):
            path = path.with_suffix(
                path.suffix + ".json" if path.suffix else ".movie.json"
            )

        # Validate before writing, including a recursive guard against accidentally
        # stuffing the original HTML source into a JSON project.
        project = json.loads(project_text)
        if project.get("format") != PROJECT_FORMAT:
            return {"ok": False, "error": "Invalid movie project format."}
        forbidden = {"html", "sourcehtml", "rawhtml", "documenthtml"}
        stack = [project]
        while stack:
            value = stack.pop()
            if isinstance(value, dict):
                for key, child in value.items():
                    if str(key).lower() in forbidden:
                        return {
                            "ok": False,
                            "error": f"Forbidden raw HTML field: {key}",
                        }
                    stack.append(child)
            elif isinstance(value, list):
                stack.extend(value)

        project.setdefault("meta", {})["modifiedAt"] = time.strftime(
            "%Y-%m-%dT%H:%M:%S%z"
        )
        tmp = path.with_suffix(path.suffix + ".tmp")
        tmp.write_text(
            json.dumps(project, ensure_ascii=False, indent=2), encoding="utf-8"
        )
        os.replace(tmp, path)
        return {
            "ok": True,
            "path": str(path),
            "name": path.name,
            "size": path.stat().st_size,
        }

    def export_blender(
        self,
        project_text: str,
        visuals_text: str,
        suggested_name: str,
        options_text: str = "{}",
    ) -> dict:
        """Build a standalone .blend with an Assets scene and a Movie scene."""
        if self._window is None:
            return {"ok": False, "error": "Editor window is not ready."}

        blender = self._blender_executable or _find_blender_executable()
        if blender is None:
            return {
                "ok": False,
                "error": (
                    "Blender was not found. Install Blender, or set the "
                    "BLENDER_EXECUTABLE environment variable to the Blender "
                    "executable and restart the editor."
                ),
            }
        self._blender_executable = blender

        try:
            project = json.loads(project_text)
            visuals = json.loads(visuals_text) if visuals_text else {}
            options = json.loads(options_text) if options_text else {}
        except json.JSONDecodeError as exc:
            return {"ok": False, "error": f"Invalid export data: {exc}"}
        if project.get("format") != PROJECT_FORMAT:
            return {"ok": False, "error": "Invalid movie project format."}

        forbidden = {"html", "sourcehtml", "rawhtml", "documenthtml"}
        stack = [project]
        while stack:
            value = stack.pop()
            if isinstance(value, dict):
                for key, child in value.items():
                    if str(key).lower() in forbidden:
                        return {
                            "ok": False,
                            "error": f"Forbidden raw HTML field: {key}",
                        }
                    stack.append(child)
            elif isinstance(value, list):
                stack.extend(value)

        dialog_type = getattr(
            getattr(self._webview, "FileDialog", object),
            "SAVE",
            getattr(self._webview, "SAVE_DIALOG", 30),
        )
        safe_suggestion = Path(suggested_name or "movie.blend").name
        if not safe_suggestion.lower().endswith(".blend"):
            safe_suggestion += ".blend"
        result = self._window.create_file_dialog(
            dialog_type,
            directory=str(ROOT),
            save_filename=safe_suggestion,
            file_types=("Blender project (*.blend)",),
        )
        if not result:
            return {"ok": False, "cancelled": True}
        selected = result[0] if isinstance(result, (tuple, list)) else result
        output_path = Path(selected).expanduser()
        if output_path.suffix.lower() != ".blend":
            output_path = Path(str(output_path) + ".blend")

        output_path.parent.mkdir(parents=True, exist_ok=True)
        temporary_output = output_path.with_name(
            f".{output_path.stem}.exporting-{os.getpid()}-{time.time_ns()}.blend"
        )
        try:
            with tempfile.TemporaryDirectory(prefix="unlim8ted-blender-") as temp_name:
                temp_dir = Path(temp_name)
                visuals = _materialize_blender_visuals(visuals, temp_dir)
                payload_path = temp_dir / "export-payload.json"
                script_path = temp_dir / "unlim8ted_blender_export.py"
                payload_path.write_text(
                    json.dumps(
                        {"project": project, "visuals": visuals, "options": options},
                        ensure_ascii=False,
                    ),
                    encoding="utf-8",
                )
                script_path.write_text(BLENDER_EXPORT_SCRIPT, encoding="utf-8")
                command = [
                    str(blender),
                    "--background",
                    "--factory-startup",
                    "--python-exit-code",
                    "1",
                    "--python",
                    str(script_path),
                    "--",
                    "--payload",
                    str(payload_path),
                    "--output",
                    str(temporary_output),
                ]
                run_options = {
                    "cwd": str(ROOT),
                    "capture_output": True,
                    "text": True,
                    "timeout": 60 * 60,
                    "check": False,
                }
                if os.name == "nt":
                    run_options["creationflags"] = getattr(
                        subprocess, "CREATE_NO_WINDOW", 0
                    )
                completed = subprocess.run(command, **run_options)
                if completed.returncode != 0:
                    diagnostic = "\n".join(
                        line
                        for line in (completed.stdout + "\n" + completed.stderr).splitlines()
                        if line.strip()
                    )[-8000:]
                    return {
                        "ok": False,
                        "error": (
                            "Blender could not build the project."
                            + (f"\n\n{diagnostic}" if diagnostic else "")
                        ),
                    }
                if not temporary_output.is_file() or temporary_output.stat().st_size < 16:
                    return {
                        "ok": False,
                        "error": "Blender finished without creating a valid .blend file.",
                    }
                with temporary_output.open("rb") as exported:
                    header = exported.read(8)
                    valid_signature = (
                        header.startswith(b"BLENDER")
                        or header.startswith(b"\x1f\x8b")
                        or header.startswith(b"\x28\xb5\x2f\xfd")
                    )
                    if not valid_signature:
                        return {
                            "ok": False,
                            "error": "Blender returned an invalid project file.",
                        }
                os.replace(temporary_output, output_path)
        except subprocess.TimeoutExpired:
            return {
                "ok": False,
                "error": "Blender export exceeded the one-hour safety limit.",
            }
        except (OSError, ValueError) as exc:
            return {"ok": False, "error": f"Could not export Blender project: {exc}"}
        finally:
            try:
                temporary_output.unlink(missing_ok=True)
            except OSError:
                pass

        return {
            "ok": True,
            "path": str(output_path),
            "name": output_path.name,
            "size": output_path.stat().st_size,
            "assetCount": len(project.get("assets", {})),
            "sceneCount": len(project.get("scenes", [])),
        }


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Unlim8ted desktop movie timeline editor"
    )
    parser.add_argument(
        "--no-auto-install",
        action="store_true",
        help="Do not automatically install pywebview if it is missing",
    )
    parser.add_argument(
        "--debug", action="store_true", help="Enable pywebview debug tools"
    )
    args = parser.parse_args()

    try:
        webview = _ensure_pywebview(auto_install=not args.no_auto_install)
    except Exception as exc:
        print(f"Could not start the desktop editor: {exc}", file=sys.stderr)
        raise SystemExit(1) from exc

    print("[startup] pywebview imported", flush=True)
    api = DesktopApi(webview)
    server, url = _start_editor_server()
    print(f"[startup] editor HTTP server ready at {url}", flush=True)
    icon_path = _ensure_app_icon()
    window_options = {
        # _start_editor_server() does an actual /health request before returning,
        # so the URL is safe to give WebView2 immediately. Starting about:blank
        # and calling load_url from webview.start() caused a much worse Windows
        # backend race where the native window could remain blank/frozen forever.
        "url": url,
        "js_api": api,
        "width": 1500,
        "height": 940,
        "min_size": (1080, 700),
        "text_select": True,
        "icon": str(icon_path),
    }
    try:
        print("[startup] creating window descriptor", flush=True)
        try:
            window = webview.create_window(
                f"Unlim8ted Movie Editor {APP_VERSION}", **window_options
            )
        except TypeError:
            window_options.pop("icon", None)
            window = webview.create_window(
                f"Unlim8ted Movie Editor {APP_VERSION}", **window_options
            )
    except Exception:
        server.shutdown()
        server.server_close()
        raise
    api.attach(window)
    print("[startup] window descriptor created; entering GUI loop", flush=True)

    print(f"Unlim8ted Movie Editor {APP_VERSION}", flush=True)
    print(f"Desktop window mode at {url}")
    print("Source HTML is loaded only when you choose it in the editor.")
    try:
        # No startup callback/navigation hop. The HTTP worker is already proven
        # ready, and WebView2 gets one URL exactly once during native creation.
        webview.start(debug=args.debug)
        print("[startup] GUI loop exited normally", flush=True)
    finally:
        server.shutdown()
        server.server_close()


if __name__ == "__main__":
    main()
